It is now easy to see that we can apply our refined algorithm for the single-machine setting to this setting as well. The key idea is to apply our trimming strategy point-wise, for each of the $m$ (independent) entries of the vectors.
\begin{algorithm}[H]
\caption{Refined algorithm for $m$ machines}
\begin{subequations}
\begin{align}
    S_0 &= \{0\},\label{eq:1st}\\
    L_{j - 1} &= S_{j - 1} \cap [0..d_j - p_j]^m,\label{eq:adapted_2nd_1}\\
    \widetilde S_j &= L_{j-1} + \{0, p_j \cdot e_1, \ldots, p_j \cdot e_m\},\label{eq:adapted_3rd}\\
    S_{j} &= \widetilde S_{j} \cup S_{j-1},\label{eq:adapted_4th}
\end{align}
\end{subequations}
where $j \in [n]$.
\end{algorithm}
